 Object.assign(pack.CARD_DATA.tasks['5C8425'],structuredClone(review.task));
 pack.CARD_DATA.items['crimea-source-art-memory'].taskScopes['5C8425']=review.taskScope;
 pack.CARD_LEARNING['crimea-source-art-memory']=structuredClone(review.learning);
 for(const [key,value] of Object.entries(review.answers)){
  answers[key]=structuredClone(value);
  Object.assign(pack.CARD_CATEGORY_ANSWERS[key],{text:value.text,question:value.question,title:value.title});
 }
